.isw__open{min-height:44px;padding:0 18px;border:0;border-radius:999px;background:#0a64d6;color:#fff;font:600 17px -apple-system,system-ui,sans-serif;cursor:pointer}
.isw__scrim{position:fixed;inset:0;z-index:20;display:flex;align-items:flex-end;background:rgba(0,0,0,.4)}
.isw__scrim[hidden]{display:none}
.isw{width:100%;min-height:50%;border-radius:10px 10px 0 0;background:#f2f2f7;font-family:-apple-system,'SF Pro Text',system-ui,sans-serif;animation:isw-in .3s ease-out}
@keyframes isw-in{from{transform:translateY(100%)}}
@media (prefers-reduced-motion:reduce){.isw{animation:none}}
.isw__grab{width:36px;height:5px;margin:6px auto 0;border-radius:3px;background:#c7c7cc}
.isw__h{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:4px 8px}
.isw__h h2{margin:0;font-size:17px;font-weight:600}
.isw__h button{justify-self:start;min-height:44px;padding:0 8px;border:0;background:none;color:#0a64d6;font:17px -apple-system,system-ui,sans-serif;cursor:pointer}
.isw__h .isw__done{justify-self:end;font-weight:600}
.isw__b{padding:12px 16px}
.isw__b label{display:grid;gap:6px;font-size:13px;color:#3c3c43}
.isw__b input{min-height:44px;padding:0 12px;border:0;border-radius:10px;background:#fff;font:17px -apple-system,system-ui,sans-serif}

